import numpy as np, json, os
from PIL import Image
TX='/home/user/dota_work/mc/npm/mca/package/minecraft-assets/data/1.21.11/blocks/'
if not os.path.isdir(TX): TX=TX.replace('1.21.11','1.21.9')
GRASS=np.array([0x91,0xBD,0x59])/255; FOL=np.array([0x77,0xAB,0x2F])/255; SPR=np.array([0x61,0x99,0x61])/255; BIR=np.array([0x80,0xA7,0x55])/255
def avg(tex,tint=None):
    p=TX+tex+'.png'
    im=np.asarray(Image.open(p).convert('RGBA')).astype(np.float32)/255
    im=im[:16] if im.shape[0]>im.shape[1] else im
    a=im[...,3]>0.5
    c=im[...,:3][a].mean(0)
    if tint is not None: c=c*tint
    return [round(float(x)*255) for x in c]
# name -> texture used for color (top for ground, side for building)
