LEAVES={'oak_leaves':('oak_leaves',FOL),'dark_oak_leaves':('dark_oak_leaves',FOL),'spruce_leaves':('spruce_leaves',SPR),'birch_leaves':('birch_leaves',BIR),'jungle_leaves':('jungle_leaves',FOL),'azalea_leaves':'azalea_leaves','flowering_azalea_leaves':'flowering_azalea_leaves','cherry_leaves':'cherry_leaves','pale_oak_leaves':'pale_oak_leaves','nether_wart_block':'nether_wart_block','shroomlight':'shroomlight','mangrove_leaves':('mangrove_leaves',np.array([0x8D,0xB1,0x27])/255),'acacia_leaves':('acacia_leaves',FOL),'moss_block':'moss_block'}
FLOWERS={'poppy':'poppy','dandelion':'dandelion','cornflower':'cornflower','oxeye_daisy':'oxeye_daisy','azure_bluet':'azure_bluet','allium':'allium','blue_orchid':'blue_orchid','red_tulip':'red_tulip','orange_tulip':'orange_tulip','pink_tulip':'pink_tulip','white_tulip':'white_tulip','lily_of_the_valley':'lily_of_the_valley','short_grass':('short_grass',GRASS),'fern':('fern',GRASS),'red_mushroom':'red_mushroom','brown_mushroom':'brown_mushroom','torchflower':'torchflower','bush':('bush',GRASS),'firefly_bush':'firefly_bush','short_dry_grass':'short_dry_grass','dead_bush':'dead_bush'}
out={}
for nm,d in (('ground',GROUND_TOP),('build',BUILD),('leaves',LEAVES),('flower',FLOWERS)):
    o={}
    for k,v in d.items():
        t,ti=(v if isinstance(v,tuple) else (v,None))
        try: o[k]=avg(t,ti)
        except Exception as e: print('MISS',k,t,e)
    out[nm]=o
json.dump(out,open('/home/user/dota_work/mc/palette.json','w'),indent=0)
print({k:len(v) for k,v in out.items()}, TX)
